import math

def area(a, b):
    return math.sqrt((a + b) * (a + b) * (-a + b) * a)

def semi_perimeter(a, b):
    return (a + b + b) / 2

def inradius(a, b):
    s = semi_perimeter(a, b)
    A = area(a, b)
    return A / s

def excircle_radius_a(a, b):
    s = semi_perimeter(a, b)
    A = area(a, b)
    return A / (s - a)

def excircle_radius_b(a, b):
    s = semi_perimeter(a, b)
    A = area(a, b)
    return A / (s - b)

def find_min_perimeter():
    min_perimeter = float('inf')
    best_triangle = None
    for a in range(1, 1000):
        for b in range(1, 1000):
            if 2 * b > a:  # Triangle inequality
                r = inradius(a, b)
                r_a = excircle_radius_a(a, b)
                r_b = excircle_radius_b(a, b)
                if math.isclose(r + r_a, 2 * r_b) and math.isclose(r_a + r, 2 * r_b):
                    perimeter = a + 2 * b
                    if perimeter < min_perimeter:
                        min_perimeter = perimeter
                        best_triangle = (a, b)
    return min_perimeter, best_triangle

min_perimeter, best_triangle = find_min_perimeter()
